/* Arqueo Express v1.1 — datos locales, sin servicios externos.
 * Montos registrados en pesos colombianos enteros. Documento fiscal DIAN NO incluido. */
'use strict';
const KEY='arqueo-express.v1';
const METHODS=[['efectivo','Efectivo'],['transferencia','Transferencia bancaria'],['nequi','Nequi'],['daviplata','Daviplata'],['debito','Tarjeta débito'],['credito','Tarjeta crédito'],['qr','QR / Llave'],['cheque','Cheque'],['otro','Otro']];
// Cada clave incluye el tipo: $1.000 como moneda y como billete son diferentes.
const CASH_DENOMS=[
 {key:'m20',type:'coin',value:20},
 {key:'m50',type:'coin',value:50},
 {key:'m100',type:'coin',value:100},
 {key:'m200',type:'coin',value:200},
 {key:'m500',type:'coin',value:500},
 {key:'m1000',type:'coin',value:1000},
 {key:'b1000',type:'bill',value:1000},
 {key:'b2000',type:'bill',value:2000},
 {key:'b5000',type:'bill',value:5000},
 {key:'b10000',type:'bill',value:10000},
 {key:'b20000',type:'bill',value:20000},
 {key:'b50000',type:'bill',value:50000},
 {key:'b100000',type:'bill',value:100000}
];
const FLOW_TYPES=[
 ['gasto','Gasto operativo','out','Arrendamiento, servicios, papelería, transporte, etc.'],
 ['nomina_otro','Otro pago laboral','out','Prestaciones, liquidación u otros pagos laborales'],
 ['pago_proveedor_directo','Pago a proveedor sin factura asociada','out','Salida a un proveedor que no modifica una cuenta por pagar'],
 ['retiro','Retiro de caja','out','Sacar efectivo de la caja hacia custodia'],
 ['ingreso_caja','Ingreso de base adicional','in','Dinero adicional entregado a la caja; no es una venta'],
 ['ingreso_otro','Otro ingreso','in','Ingreso no asociado a una factura de venta'],
 ['egreso_otro','Otro egreso','out','Salida no clasificada en otra categoría'],
 ['devolucion_cliente','Devolución a cliente','out','Dinero devuelto (sin nota fiscal ni ajuste automático de cartera)'],
 ['reembolso_proveedor','Reembolso de proveedor','in','Dinero recibido del proveedor (sin ajuste automático de cartera)']
];
const LABELS={venta:'Pago de venta',compra:'Pago de compra',abono_cliente:'Abono de cliente',abono_proveedor:'Abono a proveedor',gasto:'Gasto operativo',nomina:'Pago de nómina',anticipo:'Adelanto de nómina',nomina_otro:'Otro pago laboral',pago_proveedor_directo:'Pago directo a proveedor',retiro:'Retiro de caja',ingreso_caja:'Ingreso de base adicional',ingreso_otro:'Otro ingreso',egreso_otro:'Otro egreso',devolucion_cliente:'Devolución a cliente',reembolso_proveedor:'Reembolso de proveedor',reverso:'Reverso de movimiento'};
const NAV=[['inicio','dashboard','Panel del cajero'],['caja','wallet','Abrir y cerrar caja'],['registrar','plus-circle','Cobros y pagos'],['documentos','file-text','Ventas y compras'],['cartera','users','Cartera y pagos'],['nomina','briefcase','Nómina'],['movimientos','list','Movimientos'],['reportes','chart','Reportes'],['ajustes','settings','Configuración']];
const ICONS={
 dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/>',
 wallet:'<rect x="2" y="5" width="20" height="15" rx="3"/><path d="M2 9h20M17 15h1"/><path d="M5 5V3h14v2"/>',
 'plus-circle':'<circle cx="12" cy="12" r="9"/><path d="M12 8v8M8 12h8"/>',
 'file-text':'<path d="M7 2h7l5 5v14H7a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2Z"/><path d="M14 2v6h5M9 12h6M9 16h6"/>',
 users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v1"/>',
 briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v3M3 12h18M10 12v2h4v-2"/>',
 list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1"/>',
 chart:'<path d="M4 20V10M10 20V4M16 20v-8M22 20H2"/>',
 settings:'<circle cx="12" cy="12" r="3"/><path d="m19.5 14.5 1.2 1.5-2 3.5-1.9-.4a8 8 0 0 1-2 1.1l-.5 1.9h-4l-.5-1.9a8 8 0 0 1-2-1.1l-1.9.4-2-3.5 1.2-1.5a9 9 0 0 1 0-2.9L4 10l2-3.5 1.9.4a8 8 0 0 1 2-1.1L10.4 4h4l.5 1.8a8 8 0 0 1 2 1.1l1.9-.4 2 3.5-1.2 1.6a9 9 0 0 1 0 2.9Z" transform="translate(-.4 -1) scale(1.03)"/>',
 arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',close:'<path d="M18 6 6 18M6 6l12 12"/>', check:'<path d="m5 12 4 4L19 6"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v5M12 7h.01"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 18v3h16v-3"/>',upload:'<path d="M12 16V4m-4 4 4-4 4 4M4 18v3h16v-3"/>',printer:'<path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><path d="M6 14h12v8H6z"/>', receipt:'<path d="M4 3h16v18l-4-2-4 2-4-2-4 2V3Z"/><path d="M8 8h8M8 12h8"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',filter:'<path d="M3 4h18l-7 8v7l-4 2v-9L3 4Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',hand:'<path d="M8 11V6a2 2 0 0 1 4 0v4-6a2 2 0 0 1 4 0v7-4a2 2 0 0 1 4 0v8a7 7 0 0 1-7 7h-1a8 8 0 0 1-6-3l-4-5a2 2 0 0 1 3-3l3 3"/>',chevron:'<path d="m9 18 6-6-6-6"/>',coin:'<circle cx="12" cy="12" r="9"/><path d="M15 8c-1-1-5-1-5 1s5 1 5 4-5 3-6 2M12 6v12"/>',pie:'<path d="M21 13A9 9 0 1 1 11 3v9h10Z"/><path d="M21 9h-6V3a9 9 0 0 1 6 6Z"/>'};
const icon=(k)=>`<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[k]||ICONS.info}</svg>`;
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n)=>'$ '+Math.round(Number(n)||0).toLocaleString('es-CO');
const num=(n)=>Math.round(Number(n)||0);
const localDate=(d=new Date())=>{const z=(n)=>String(n).padStart(2,'0');return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}`};
const dt=(d)=>new Date(d).toLocaleString('es-CO',{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const dateOnly=(d)=>new Date(d).toLocaleDateString('es-CO',{year:'numeric',month:'short',day:'numeric'});
const uid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const defaultState=()=>({version:1,settings:{name:'Mi negocio'},shifts:[],documents:[],movements:[],payrolls:[]});
function load(){try{const raw=localStorage.getItem(KEY);if(!raw)return defaultState();const v=JSON.parse(raw);if(!validData(v))return defaultState();return v}catch{return defaultState()}}
function validData(x){return x&&x.version===1&&x.settings&&typeof x.settings.name==='string'&&Array.isArray(x.shifts)&&Array.isArray(x.documents)&&Array.isArray(x.movements)&&Array.isArray(x.payrolls)}
let state=load();
let ui={page:'inicio',registerTab:'venta',docTab:'todos',creditTab:'cobrar',movFilter:'todos',movSearch:'',docSearch:'',modal:null,recordID:null,reportFrom:localDate(new Date(new Date().setDate(1))),reportTo:localDate(),payrollEmployee:'',closingDenoms:{},closingCount:'',openingDenoms:{}};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('No se pudo guardar. Exporta una copia de seguridad.','error');return false}}
function commit(fn,msg){const before=JSON.stringify(state);fn();if(!save()){state=JSON.parse(before);render();return false}render();if(msg)toast(msg);return true}
function toast(msg,type=''){const el=document.querySelector('#toast');if(!el)return;el.innerHTML=`<div class="toast-item ${type}">${esc(msg)}</div>`;clearTimeout(window.__toastTimeout);window.__toastTimeout=setTimeout(()=>el.innerHTML='',3600)}
function activeShift(){return state.shifts.find(s=>s.status==='open')||null}
function lastShift(){return [...state.shifts].sort((a,b)=>b.openedAt.localeCompare(a.openedAt))[0]||null}
function currentMovements(){const shift=activeShift();return shift?state.movements.filter(m=>m.shiftId===shift.id):[]}
function shiftMovements(shiftId){return state.movements.filter(m=>m.shiftId===shiftId)}
function sum(arr,fn){return arr.reduce((t,x)=>t+(fn?fn(x):num(x)),0)}
function signed(m){return m.direction==='in'?num(m.amount):-num(m.amount)}
function shiftExpected(shift){return shift.base+sum(shiftMovements(shift.id).filter(m=>m.method==='efectivo'),signed)}
function paidOf(doc){const direction=doc.kind==='sale'?'in':'out';const result=sum(state.movements.filter(m=>m.documentId===doc.id),m=>m.direction===direction?m.amount:-m.amount);return Math.max(0,Math.min(doc.total,result))}
function balanceOf(doc){return Math.max(0,doc.total-paidOf(doc))}
function statusOf(doc){const paid=paidOf(doc);return paid>=doc.total?'Pagada':paid===0?'Pendiente':'Parcial'}
function outstanding(kind){return sum(state.documents.filter(d=>d.kind===kind),balanceOf)}
function remainingAdvance(employee){const e=employee.trim().toLocaleLowerCase('es');const entries=state.movements.filter(m=>m.category==='anticipo'&&String(m.party||'').trim().toLocaleLowerCase('es')===e);const advances=sum(entries.filter(m=>!state.movements.some(r=>r.reversalOf===m.id)),m=>m.amount);const deducted=sum(state.payrolls.filter(p=>!p.voided&&p.employee.trim().toLocaleLowerCase('es')===e),p=>p.appliedAdvance);return Math.max(0,advances-deducted)}
function methodName(m){return (METHODS.find(x=>x[0]===m)||[,'Otro'])[1]}
function catName(m){return LABELS[m.category]||m.category||'Movimiento'}
function totalByMethod(movs,method){return sum(movs.filter(m=>m.method===method),signed)}
function signAmount(m){return `<span class="money ${m.direction==='in'?'positive':'negative'}">${m.direction==='in'?'+':'−'}${fmt(m.amount)}</span>`}
function statusBadge(doc){const v=statusOf(doc);return `<span class="status ${v==='Pendiente'?'amber':v==='Parcial'?'gray':''}"><span class="bullet"></span>${v}</span>`}
function addMovement(p){state.movements.push({id:uid(),createdAt:new Date().toISOString(),shiftId:activeShift().id,...p,amount:num(p.amount)})}
function pageTitle(title,subtitle,action=''){return `<div class="page-heading"><div><div class="title-label">ARQUEO EXPRESS / ${esc(ui.page.toUpperCase())}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action?`<div class="actions no-print">${action}</div>`:''}</div>`}
function metric(label,value,foot,ic='coin',tone=''){return `<div class="metric"><div class="metric-top"><span class="metric-label">${esc(label)}</span><span class="iconbox ${tone}">${icon(ic)}</span></div><div class="metric-value" title="${esc(value)}">${esc(value)}</div><div class="metric-foot">${esc(foot)}</div></div>`}
function empty(title,description,ic='receipt'){return `<div class="empty"><div class="empty-icon">${icon(ic)}</div><b>${esc(title)}</b><p>${esc(description)}</p></div>`}
function button(text,action,cls='btn',extra=''){return `<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`}
function primary(text,action,extra=''){return button(`${icon('plus')}${esc(text)}`,action,'btn primary',extra)}
function input(label,name,type='text',value='',opts=''){return `<div class="field"><label for="f_${name}">${esc(label)}</label><input id="f_${name}" name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" ${opts}/></div>`}
function textarea(label,name,placeholder=''){return `<div class="field full"><label for="f_${name}">${esc(label)}</label><textarea id="f_${name}" name="${esc(name)}" placeholder="${esc(placeholder)}"></textarea></div>`}
function select(label,name,items,selected='',opts=''){return `<div class="field"><label for="f_${name}">${esc(label)}</label><select id="f_${name}" name="${esc(name)}" ${opts}>${items.map(x=>`<option value="${esc(x[0])}" ${x[0]===selected?'selected':''}>${esc(x[1])}</option>`).join('')}</select></div>`}
function methodOptions(selected='efectivo'){return METHODS.map(x=>`<option value="${x[0]}" ${x[0]===selected?'selected':''}>${esc(x[1])}</option>`).join('')}
function paymentRow(value='',method='efectivo'){return `<div class="payment-row"><select name="pay_method" aria-label="Método de pago">${methodOptions(method)}</select><input name="pay_amount" type="number" inputmode="numeric" min="0" step="1" placeholder="Monto $" value="${esc(value)}" aria-label="Monto del pago"><button type="button" class="mini-remove" data-action="remove-payment" title="Quitar método">${icon('close')}</button></div>`}
function paymentBlock(){return `<div class="payment-area"><h3>Métodos de pago</h3><p>Registra uno o varios métodos. Si el total pagado es menor que la factura, la diferencia quedará a crédito.</p><div class="payments">${paymentRow()}</div>${button(`${icon('plus')} Añadir otro método`,'add-payment','btn small')}<div class="payment-total"><span>Pagado ahora: <strong class="calc-paid">${fmt(0)}</strong></span><span>Saldo a crédito: <b class="calc-credit">${fmt(0)}</b></span></div></div>`}
function readPayments(form,maximum){const rows=[...form.querySelectorAll('.payment-row')];const payments=rows.map(r=>({method:r.querySelector('[name=pay_method]').value,amount:num(r.querySelector('[name=pay_amount]').value)})).filter(p=>p.amount>0);if(rows.some(r=>Number(r.querySelector('[name=pay_amount]').value)<0))throw Error('Los pagos no pueden ser negativos.');if(payments.some(p=>p.amount<=0))throw Error('El monto debe ser positivo.');const total=sum(payments,p=>p.amount);if(total>maximum)throw Error('La suma de pagos supera el valor pendiente.');return payments}
function denominationTotal(counts){return CASH_DENOMS.reduce((total,d)=>total+d.value*(Math.max(0,num(counts?.[d.key]))),0)}
function readDenominationCounts(form){const values={};for(const d of CASH_DENOMS){const field=form.querySelector(`[name="denom_${d.key}"]`);if(!field)throw Error('Falta una denominación.');const raw=field.value.trim(),n=raw===''?0:Number(raw);if(!Number.isSafeInteger(n)||n<0||n>100000)throw Error('Las cantidades deben ser números enteros entre 0 y 100.000.');values[d.key]=n}return values}
function denominationCounter(mode,counts={}){const group=(type,title,explain)=>`<section class="denom-section ${type}"><div class="denom-heading"><div><h3>${title}</h3><p>${explain}</p></div><span class="denom-tag">${CASH_DENOMS.filter(d=>d.type===type).length} denominaciones</span></div><div class="denom-list">${CASH_DENOMS.filter(d=>d.type===type).map(d=>{const qty=Math.max(0,num(counts[d.key]));return `<div class="denom-row" data-denom-row="${d.key}"><div class="money-symbol ${d.type}" aria-hidden="true">${d.type==='coin'?'$':'▣'}</div><div class="denom-description"><b>${fmt(d.value)}</b><small>${type==='coin'?'Moneda':'Billete'}${d.key==='b1000'?' · diseño anterior':''}</small></div><div class="denom-controls"><button type="button" class="stepper" data-action="change-denom" data-mode="${mode}" data-key="${d.key}" data-delta="-1" aria-label="Quitar una ${type==='coin'?'moneda':'billete'} de ${fmt(d.value)}">−</button><input class="denom-qty" type="number" min="0" max="100000" step="1" inputmode="numeric" data-counter="${mode}" data-key="${d.key}" name="denom_${d.key}" value="${qty||''}" placeholder="0" aria-label="Cantidad de ${type==='coin'?'monedas':'billetes'} de ${fmt(d.value)}"><button type="button" class="stepper" data-action="change-denom" data-mode="${mode}" data-key="${d.key}" data-delta="1" aria-label="Añadir una ${type==='coin'?'moneda':'billete'} de ${fmt(d.value)}">+</button></div><span class="denom-subtotal" data-subtotal="${d.key}">${fmt(d.value*qty)}</span></div>`}).join('')}</div></section>`;return `<div class="cash-denom-counter" data-mode="${mode}"><div class="denom-columns">${group('bill','Billetes','Cuenta los billetes de tu gaveta')}${group('coin','Monedas','Incluye $20 y la moneda de $1.000')}</div></div>`}
function updateDenominationCounter(mode){const root=document.querySelector(`.cash-denom-counter[data-mode="${mode}"]`);if(!root)return 0;let total=0;const values={};for(const d of CASH_DENOMS){const el=root.querySelector(`[name="denom_${d.key}"]`);const n=el?Math.max(0,Math.min(100000,num(el.value))):0;values[d.key]=n;total+=n*d.value;const subtotal=root.querySelector(`[data-subtotal="${d.key}"]`);if(subtotal)subtotal.textContent=n?fmt(n*d.value):'—'}if(mode==='opening'){ui.openingDenoms=values;const live=document.getElementById('opening-base-total');if(live)live.textContent=fmt(total);const note=document.getElementById('opening-pieces');if(note)note.textContent=sum(Object.values(values),num)+' piezas contadas';const summary=document.getElementById('opening-confirm-total');if(summary)summary.textContent=fmt(total)}else{ui.closingDenoms=values;const live=document.getElementById('denom-total');if(live)live.textContent=fmt(total);const counted=document.querySelector('#close-form [name=counted]');if(counted)counted.value=total;updateClosePreview()}return total}
function requireShift(){if(activeShift())return true;toast('Primero debes abrir la caja.','error');ui.page='caja';render();return false}
function render(){const app=document.querySelector('#app');if(!app)return;const shift=activeShift();app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('wallet')}</div><div><b>Arqueo Express</b><span>CONTROL DE CAJA</span></div></div><div class="nav-section">Operación</div>${NAV.slice(0,6).map(n=>navLink(n)).join('')}<div class="nav-section">Administración</div>${NAV.slice(6).map(n=>navLink(n)).join('')}<div class="sidebar-spacer"></div><div class="side-footer"><span class="online-dot"></span> Datos guardados en este dispositivo<br><span style="color:#7794c0">Versión 1.1 · Sin suscripción</span></div></aside><main class="main"><header class="topbar"><span class="brand-compact" style="display:none">Arqueo Express</span><div class="topbar-left"><span class="status ${shift?'':'gray'}"><span class="bullet"></span>${shift?'Caja abierta':'Caja cerrada'}</span></div><div class="topbar-right"><span class="business-name">${esc(state.settings.name)}</span><div class="avatar">${esc(state.settings.name.charAt(0).toUpperCase()||'N')}</div></div></header><div class="main-content">${renderPage()}</div></main></div><nav class="mobile-nav">${[['inicio','dashboard','Hoy'],['caja','wallet','Caja'],['registrar','plus-circle','Cobrar'],['cartera','users','Cartera'],['menu','settings','Más']].map(n=>`<button data-page="${n[0]}" class="${ui.page===n[0]?'active':''}">${icon(n[1])}${n[2]}</button>`).join('')}</nav>${renderModal()}`;
 // Responsive topbar label without JS polling
 if(matchMedia('(max-width:760px)').matches){const b=app.querySelector('.brand-compact');b.style.display='block'}
}
function navLink(n){return `<button class="nav-link ${ui.page===n[0]?'active':''}" data-page="${n[0]}">${icon(n[1])}<span>${esc(n[2])}</span></button>`}
function renderPage(){switch(ui.page){case 'inicio':return renderDashboard();case 'caja':return renderCash();case 'registrar':return renderRegister();case 'documentos':return renderDocuments();case 'cartera':return renderCredits();case 'nomina':return renderPayroll();case 'movimientos':return renderMovements();case 'reportes':return renderReports();case 'ajustes':return renderSettings();case 'menu':return renderMenu();default:return renderDashboard()}}
function renderDashboard(){
 const shift=activeShift(),last=lastShift(),today=localDate();
 const daymovs=state.movements.filter(m=>localDate(new Date(m.createdAt))===today),salesDocs=state.documents.filter(d=>d.kind==='sale'&&localDate(new Date(d.createdAt))===today);
 const paidDay=daymovs.filter(m=>m.category==='venta'||m.category==='abono_cliente'),cash=shift?shiftExpected(shift):0;
 const hero=shift?`<section class="cashier-hero open"><div class="cashier-hero-main"><div class="eyebrow-light">${icon('coin')} EFECTIVO ESTIMADO EN GAVETA</div><strong class="hero-amount">${fmt(cash)}</strong><p>Turno de <b>${esc(shift.operator)}</b> · Abierto ${esc(dt(shift.openedAt))}</p><div class="cashier-hero-actions"><button class="hero-button main-action" type="button" data-action="quick" data-page-target="registrar" data-tab="venta">${icon('receipt')} Cobrar venta</button><button class="hero-button" type="button" data-action="quick" data-page-target="registrar" data-tab="gasto">${icon('minus')} Registrar salida</button><button class="hero-button outline" type="button" data-action="goto-caja">${icon('wallet')} Ver turno</button></div></div><div class="hero-decoration" aria-hidden="true">${icon('wallet')}</div></section>`:`<section class="cashier-hero closed"><div class="cashier-hero-main"><div class="eyebrow-light">INICIO DEL TURNO</div><h2>Tu caja está cerrada</h2><p>Cuenta monedas y billetes antes de registrar operaciones.${last&&last.status==='closed'?` Base dejada en el último cierre: <b>${fmt(last.nextBase)}</b>.`:''}</p><div class="cashier-hero-actions"><button class="hero-button main-action" type="button" data-action="goto-caja">${icon('wallet')} Abrir caja ahora</button></div></div><div class="hero-decoration" aria-hidden="true">${icon('wallet')}</div></section>`;
 const actions=[['Nueva venta','receipt','registrar','venta','Contado o crédito'],['Nueva compra','wallet','registrar','compra','Proveedor o mercancía'],['Registrar abono','users','cartera','','Clientes y proveedores'],['Anticipo de nómina','coin','registrar','anticipo','Personal del negocio']];
 return `${pageTitle('Panel del cajero','Operaciones del turno, sin pasos innecesarios.')} ${hero}<div class="metrics cashier-metrics">${metric('Ventas recaudadas hoy',fmt(sum(paidDay,signed)),'Ingresos registrados en ventas y abonos','coin','green')}${metric('Por cobrar a clientes',fmt(outstanding('sale')),'Créditos y saldos pendientes','users','amber')}${metric('Por pagar a proveedores',fmt(outstanding('purchase')),'Compras y pagos pendientes','receipt','pink')}${metric('Movimientos del turno',String(shift?shiftMovements(shift.id).length:0),'Cobros, pagos y otros movimientos','list')}</div><div class="grid-2 cashier-grid"><section class="panel"><div class="panel-head"><div><h2>Operaciones rápidas</h2><p>Accesos diseñados para un cajero</p></div></div><div class="panel-body"><div class="action-grid">${actions.map(a=>`<button type="button" class="action-tile" data-action="quick" data-page-target="${a[2]}" data-tab="${a[3]}">${icon(a[1])}<div><b>${a[0]}</b><span>${a[4]}</span></div></button>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><div><h2>Últimos movimientos</h2><p>Entradas y salidas registradas</p></div>${button('Ver todos','goto-movimientos','btn small')}</div>${renderMovTable(state.movements.slice(-4).reverse(),false)}</section></div><div class="section-spacer"></div><div class="panel"><div class="panel-head"><div><h2>Ventas de hoy</h2><p>Incluye ventas a crédito y pagos parciales</p></div><span class="chip">${salesDocs.length} documentos</span></div>${renderDocsTable(salesDocs.slice(-5).reverse(),false)}</div>`
}
function renderCash(){
 const shift=activeShift(),last=lastShift();let content='';
 if(shift){const movs=shiftMovements(shift.id),inCash=sum(movs.filter(m=>m.method==='efectivo'&&m.direction==='in'),m=>m.amount),outCash=sum(movs.filter(m=>m.method==='efectivo'&&m.direction==='out'),m=>m.amount),digital=sum(movs.filter(m=>m.method!=='efectivo'),signed);
 content=`<div class="summary-banner"><div><small class="muted">EFECTIVO ESPERADO EN CAJA</small><strong>${fmt(shiftExpected(shift))}</strong><small class="muted">${esc(shift.operator)} · ${esc(dt(shift.openedAt))}</small></div><span class="status">Abierta</span></div><div class="cash-flow"><div class="cash-cell"><small>Base contada</small><b>${fmt(shift.base)}</b></div><div class="cash-cell"><small>Entradas en efectivo</small><b class="positive">${fmt(inCash)}</b></div><div class="cash-cell"><small>Salidas en efectivo</small><b class="negative">${fmt(outCash)}</b></div></div><div class="section-spacer"></div>${shift.baseDenominations?`<details class="opening-details"><summary>Ver desglose de la apertura ${icon('chevron')}</summary><div class="opening-details-body">${CASH_DENOMS.filter(d=>num(shift.baseDenominations[d.key])>0).map(d=>`<div class="kv"><span>${d.type==='coin'?'Moneda':'Billete'} de ${fmt(d.value)} × ${num(shift.baseDenominations[d.key])}</span><b>${fmt(d.value*num(shift.baseDenominations[d.key]))}</b></div>`).join('')||'<p>Se abrió sin efectivo.</p>'}</div></details>`:''}<div class="hint">${icon('info')} <div>Pagos digitales netos del turno: <b>${fmt(digital)}</b>. No forman parte del efectivo de la gaveta.</div></div><button type="button" class="btn primary full close-big" data-action="show-close">${icon('check')} Contar y cerrar caja</button>`;
 } else {
 const hint=last&&last.status==='closed'?`El turno anterior dejó <b>${fmt(last.nextBase)}</b> como base. Cuenta nuevamente el efectivo físico; no lo copiamos automáticamente.`:'Cuenta físicamente todas las monedas y billetes que recibes para trabajar.';
 content=`<div class="opening-intro"><div class="opening-step">1</div><div><b>Identifica al cajero</b><p>Luego cuenta la base inicial, denominación por denominación.</p></div></div><form id="open-shift-form"><div class="open-operator">${input('Nombre del responsable','operator','text','','placeholder="Ej.: Cajero principal" autocomplete="name" required maxlength="100"')}</div><div class="opening-tip">${icon('info')} <span>${hint}</span></div><div class="denom-title-row"><div><span class="step-eyebrow">PASO 2 · CONTEO FÍSICO</span><h3>¿Cuánto dinero hay en la caja?</h3><p>Ingresa las cantidades, no los valores totales.</p></div><button type="button" class="btn small" data-action="clear-denoms" data-mode="opening">Borrar conteo</button></div>${denominationCounter('opening',ui.openingDenoms)}<div class="opening-total-card" aria-live="polite"><div><small>BASE INICIAL CALCULADA</small><strong id="opening-base-total">${fmt(denominationTotal(ui.openingDenoms))}</strong><span id="opening-pieces">${sum(Object.values(ui.openingDenoms),num)} piezas contadas</span></div><span class="calculated-chip">${icon('check')} Automático</span></div><div class="opening-note">${textarea('Nota de apertura (opcional)','note','Ej.: Caja 1, turno mañana, novedades')}</div><div class="opening-sticky-submit"><div class="sticky-total"><small>Total de apertura</small><b id="opening-confirm-total">${fmt(denominationTotal(ui.openingDenoms))}</b></div><button class="btn primary" type="submit">${icon('check')} Confirmar apertura</button></div></form>`;
 }
 const history=[...state.shifts].reverse();
 return `${pageTitle('Caja y turnos',shift?'Revisa el efectivo de la gaveta y finaliza el turno.':'Apertura guiada para cajeros · pesos colombianos.')}<div class="cash-layout ${shift?'is-open':'is-closed'}"><section class="panel cash-primary"><div class="panel-head"><div><h2>${shift?'Tu turno está activo':'Abrir caja'}</h2><p>${shift?'Disponible para cobros, pagos y retiros':'Registro inicial de billetes y monedas'}</p></div><span class="status ${shift?'':'gray'}">${shift?'En operación':'Pendiente'}</span></div><div class="panel-body">${content}</div></section><section class="panel cash-history"><div class="panel-head"><div><h2>Turnos anteriores</h2><p>Consulta cierres y diferencias</p></div></div>${history.length?`<div class="shift-history-list">${history.slice(0,8).map(s=>`<div class="shift-history-item"><div><b>${esc(s.operator)}</b><small>${esc(dt(s.openedAt))}</small><small>${s.status==='open'?'En operación':'Turno finalizado'}</small></div><div><b class="history-base">${fmt(s.base)}</b>${s.status==='closed'?button('Ver cierre','view-shift','btn small',`data-id="${s.id}"`):'<span class="status">Abierta</span>'}</div></div>`).join('')}</div>`:empty('Todavía no hay turnos','Los turnos cerrados aparecerán aquí.','clock')}</section></div>`
}
function renderRegister(){const shift=activeShift();const options=[['venta','Venta'],['compra','Compra'],['gasto','Otros movimientos'],['anticipo','Anticipo nómina'],['nomina','Pago nómina']];let body;if(ui.registerTab==='venta'||ui.registerTab==='compra'){const sale=ui.registerTab==='venta';body=`<form id="document-form"><div class="form-grid">${input(sale?'Cliente':'Proveedor','party','text','','placeholder="Nombre o razón social" required maxlength="140"')}${input('Número de documento (opcional)','number','text','','placeholder="Automático si se deja vacío" maxlength="80"')}${input('Valor total (COP)','total','number','','min="1" required step="1" placeholder="0"')}${input('Fecha de la operación','date','date',localDate(),'required')}${textarea('Concepto / observaciones','note','Productos, número de factura externa, referencia, etc.')}</div>${paymentBlock()}<div class="form-footer"><button type="submit" class="btn primary">${icon('check')} Guardar ${sale?'venta':'compra'}</button></div></form>`}else if(ui.registerTab==='gasto'){body=`<form id="flow-form"><div class="form-grid">${select('Tipo de operación','category',FLOW_TYPES.map(x=>[x[0],x[1]]))}${input('Valor (COP)','amount','number','','min="1" required step="1"')}${input('Tercero / beneficiario','party','text','','placeholder="Opcional" maxlength="140"')}${select('Método de pago','method',METHODS)}${input('Referencia / comprobante','reference','text','','placeholder="Opcional" maxlength="100"')}${textarea('Concepto o detalle','note','Describe brevemente el movimiento')}</div><div class="form-footer"><button class="btn primary" type="submit">${icon('check')} Registrar movimiento</button></div></form><div class="section-spacer"></div><div class="hint">${icon('info')} <div>Para registrar abonos a facturas, utiliza <b>Cartera y pagos</b>. Para evitar duplicidades, el pago de una compra a crédito se registra directamente contra su documento.</div></div>`}else if(ui.registerTab==='anticipo'){body=`<form id="advance-form"><div class="form-grid">${input('Empleado','employee','text','','required maxlength="140" placeholder="Nombre del empleado"')}${input('Valor del anticipo (COP)','amount','number','','min="1" required step="1"')}${select('Método de pago','method',METHODS)}${input('Referencia','reference','text','','placeholder="Opcional" maxlength="100"')}${textarea('Detalle','note','Anticipo de nómina, periodo, observaciones')}</div><div class="form-footer"><button class="btn primary" type="submit">${icon('check')} Registrar anticipo</button></div></form><div class="section-spacer"></div><div class="hint">${icon('info')} <div>El anticipo sí es una salida de dinero, pero no se vuelve a restar como salida al descontarlo del pago de nómina.</div></div>`}else{body=payrollForm()}
 return `${pageTitle('Registrar operación','Ventas, compras, pagos, adelantos y movimientos de caja.')}${!shift?`<div class="hint warning">${icon('info')} <div>Necesitas abrir un turno de caja para registrar operaciones. ${button('Ir a apertura','goto-caja','btn small')}</div></div><div class="section-spacer"></div>`:''}<section class="panel"><div class="panel-body"><div class="tabs">${options.map(o=>`<button class="tab ${ui.registerTab===o[0]?'active':''}" data-tab="${o[0]}" type="button">${o[1]}</button>`).join('')}</div>${body}</div></section>`}
function payrollForm(){return `<form id="payroll-form"><div class="form-grid">${input('Empleado','employee','text',ui.payrollEmployee,'required maxlength="140" placeholder="Nombre del empleado"')}${input('Nómina devengada a liquidar (COP)','gross','number','','min="1" step="1" required')}${select('Método para el pago neto','method',METHODS)}${input('Referencia / periodo','reference','text','','placeholder="Ej: 2026-11 quincena 1" maxlength="100"')}<div class="field full"><label class="switch-row"><input type="checkbox" name="deduct" checked> Aplicar anticipos pendientes de este empleado</label><small id="advance-info">Escribe el nombre del empleado para consultar sus anticipos.</small></div>${textarea('Observaciones','note','Pago de salario y deducción de adelantos anteriores')}</div><div class="payment-area"><h3>Liquidación estimada</h3><div class="kv"><span>Salario / valor registrado</span><b id="pay-gross">${fmt(0)}</b></div><div class="kv"><span>Anticipos aplicados</span><b id="pay-deduct">${fmt(0)}</b></div><div class="divider"></div><div class="kv"><span>Neto a entregar ahora</span><b id="pay-net" class="value-large">${fmt(0)}</b></div></div><div class="form-footer"><button class="btn primary" type="submit">${icon('check')} Guardar pago de nómina</button></div></form>`}
function docsControls(){return `<div class="table-controls no-print"><input type="search" class="search" id="doc-search" placeholder="Buscar por cliente, proveedor o N.º…" value="${esc(ui.docSearch)}"><button class="btn small ${ui.docTab==='todos'?'soft':''}" data-doc-filter="todos">Todos</button><button class="btn small ${ui.docTab==='venta'?'soft':''}" data-doc-filter="venta">Ventas</button><button class="btn small ${ui.docTab==='compra'?'soft':''}" data-doc-filter="compra">Compras</button></div>`}
function renderDocuments(){let docs=[...state.documents].reverse().filter(d=>ui.docTab==='todos'||(ui.docTab==='venta'?d.kind==='sale':d.kind==='purchase'));if(ui.docSearch){const s=ui.docSearch.toLowerCase();docs=docs.filter(d=>`${d.party} ${d.number} ${d.note||''}`.toLowerCase().includes(s))}return `${pageTitle('Ventas y compras','Documentos internos de contado, mixtos y a crédito.',primary('Nueva factura','goto-register'))}<div class="panel"><div class="panel-body">${docsControls()}</div>${renderDocsTable(docs,true)}</div><div class="section-spacer"></div><div class="hint warning">${icon('info')} <div>Los documentos de Arqueo Express son <b>registros internos de control</b>. No son facturas electrónicas emitidas o validadas por la DIAN. Puedes guardar el número real de la factura emitida por tu sistema fiscal.</div></div>`}
function renderDocsTable(docs,actions){if(!docs.length)return empty('Sin documentos','Los documentos de ventas y compras aparecerán aquí.','file-text');return `<div class="records-list"><div class="table-wrap desktop-table"><table><thead><tr><th>Documento</th><th>Tercero</th><th>Valor total</th><th>Saldo</th><th>Estado</th>${actions?'<th></th>':''}</tr></thead><tbody>${docs.map(d=>`<tr><td><span class="strong">${esc(d.number)}</span><span class="subtext">${d.kind==='sale'?'Venta':'Compra'} · ${esc(dateOnly(d.createdAt))}</span></td><td>${esc(d.party)}</td><td class="money">${fmt(d.total)}</td><td class="money">${fmt(balanceOf(d))}</td><td>${statusBadge(d)}</td>${actions?`<td>${button('Ver detalle','view-doc','btn small',`data-id="${d.id}"`)}</td>`:''}</tr>`).join('')}</tbody></table></div><div class="mobile-records">${docs.map(d=>`<div class="mobile-record"><div class="mobile-record-top"><div><b>${esc(d.number)}</b><small>${d.kind==='sale'?'Venta':'Compra'} · ${esc(dateOnly(d.createdAt))}</small></div>${statusBadge(d)}</div><div class="mobile-record-name">${esc(d.party)}</div><div class="mobile-record-bottom"><div><small>Total</small><b>${fmt(d.total)}</b></div><div><small>Saldo</small><b>${fmt(balanceOf(d))}</b></div>${actions?button('Ver','view-doc','btn small',`data-id="${d.id}"`):''}</div></div>`).join('')}</div></div>`}
function renderCredits(){const sell=ui.creditTab==='cobrar';const docs=[...state.documents].filter(d=>d.kind===(sell?'sale':'purchase')&&balanceOf(d)>0).reverse();const total=sum(docs,balanceOf);return `${pageTitle('Cartera y proveedores','Saldos, abonos parciales y pagos pendientes.') }<div class="metrics" style="grid-template-columns:repeat(2,minmax(0,1fr))">${metric('Por cobrar',fmt(outstanding('sale')),'Saldo pendiente de clientes','users','green')}${metric('Por pagar',fmt(outstanding('purchase')),'Saldo pendiente a proveedores','receipt','amber')}</div><section class="panel"><div class="panel-body"><div class="tabs"><button class="tab ${sell?'active':''}" data-credit-tab="cobrar">Cuentas por cobrar</button><button class="tab ${!sell?'active':''}" data-credit-tab="pagar">Cuentas por pagar</button></div><div class="hint">${icon('info')} <div>Saldo pendiente en ${docs.length} documento(s): <b>${fmt(total)}</b>. Registra abonos contra cada documento; se descuentan automáticamente del saldo y solo afectan al efectivo si el método es efectivo.</div></div><div class="section-spacer"></div>${docs.length?docs.map(d=>`<div class="credit-card"><div><h3>${esc(d.party)}</h3><p>${esc(d.number)} · Total ${fmt(d.total)} · Abonado ${fmt(paidOf(d))}</p></div><div class="right"><b>${fmt(balanceOf(d))}</b><small>Por ${sell?'cobrar':'pagar'}</small>${button(`${icon('plus')} Registrar abono`,'pay-doc','btn small primary',`data-id="${d.id}"`)}</div></div>`).join(''):empty('Todo al día',`No tienes cuentas por ${sell?'cobrar':'pagar'} pendientes.`,'check')}</div></section>`}
function renderPayroll(){const allEmployees=[...new Set([...state.movements.filter(m=>m.category==='anticipo').map(m=>m.party),...state.payrolls.map(p=>p.employee)].filter(Boolean))].sort();const advances=allEmployees.map(e=>({name:e,pending:remainingAdvance(e)})).filter(x=>x.pending>0);const payrolls=[...state.payrolls].filter(p=>!p.voided).reverse();return `${pageTitle('Nómina y anticipos','Control de adelantos de salario y pagos netos.',button(`${icon('plus')} Nuevo pago`,'goto-payroll','btn primary'))}<div class="metrics" style="grid-template-columns:repeat(2,minmax(0,1fr))">${metric('Anticipos pendientes',fmt(sum(advances,x=>x.pending)),'Valor por descontar en nómina','coin','amber')}${metric('Pagos registrados',String(state.payrolls.filter(p=>!p.voided).length),'Liquidaciones guardadas','briefcase','green')}</div><div class="grid-2 grid-even"><section class="panel"><div class="panel-head"><div><h2>Anticipos por aplicar</h2><p>Saldo disponible para descuento posterior</p></div></div>${advances.length?`<div class="panel-body">${advances.map(a=>`<div class="line-item"><div><b>${esc(a.name)}</b><small>Adelantos aún no compensados</small></div><div><b class="money">${fmt(a.pending)}</b></div></div>`).join('')}</div>`:empty('Sin adelantos pendientes','Los anticipos de nómina aparecerán aquí.','briefcase')}</section><section class="panel"><div class="panel-head"><div><h2>Últimos pagos de nómina</h2><p>Valor pagado = devengado menos anticipos aplicados</p></div></div>${payrolls.length?`<div class="panel-body">${payrolls.slice(0,10).map(p=>`<div class="line-item"><div><b>${esc(p.employee)}</b><small>${dt(p.createdAt)} · Devengado ${fmt(p.gross)}</small></div><div style="text-align:right"><b class="money">${fmt(p.net)}</b><small>Aplicado ${fmt(p.appliedAdvance)}</small>${button('Anular','reverse-payroll','a-link',`data-id="${p.id}"`)}</div></div>`).join('')}</div>`:empty('Sin pagos de nómina','Registra un pago de nómina desde Registrar.','briefcase')}</section></div><div class="section-spacer"></div><div class="hint warning">${icon('info')} <div>Este módulo solo controla desembolsos y anticipos: <b>no calcula obligaciones legales de nómina, seguridad social, retenciones ni desprendibles oficiales</b>.</div></div>`}
function renderMovements(){let movs=[...state.movements].reverse();if(ui.movFilter!=='todos')movs=movs.filter(m=>ui.movFilter==='entrada'?m.direction==='in':ui.movFilter==='salida'?m.direction==='out':m.method===ui.movFilter);if(ui.movSearch){const s=ui.movSearch.toLowerCase();movs=movs.filter(m=>`${m.party||''} ${m.note||''} ${m.reference||''} ${catName(m)} ${methodName(m.method)}`.toLowerCase().includes(s))}return `${pageTitle('Todos los movimientos','Trazabilidad de pagos, abonos, efectivo y transferencias.',button(`${icon('download')} Exportar CSV`,'export-moves','btn'))}<section class="panel"><div class="panel-body"><div class="table-controls"><input id="mov-search" type="search" class="search" placeholder="Buscar concepto, tercero o referencia…" value="${esc(ui.movSearch)}"><select id="mov-filter" class="select-small"><option value="todos">Todos</option><option value="entrada" ${ui.movFilter==='entrada'?'selected':''}>Entradas</option><option value="salida" ${ui.movFilter==='salida'?'selected':''}>Salidas</option>${METHODS.map(m=>`<option value="${m[0]}" ${ui.movFilter===m[0]?'selected':''}>${m[1]}</option>`).join('')}</select></div></div>${renderMovTable(movs,true)}</section>`}
function renderMovTable(movs,actions){if(!movs.length)return empty('Sin movimientos','Registra tu primera operación para comenzar el historial.','list');return `<div class="records-list"><div class="table-wrap desktop-table"><table><thead><tr><th>Operación</th><th>Tercero / referencia</th><th>Método</th><th>Valor</th>${actions?'<th></th>':''}</tr></thead><tbody>${movs.map(m=>`<tr><td><span class="strong">${esc(catName(m))}</span><span class="subtext">${esc(dt(m.createdAt))}</span></td><td><span>${esc(m.party||m.note||'—')}</span><span class="subtext">${esc(m.reference||((m.party&&m.note)?m.note:''))}</span></td><td><span class="pill-method">${esc(methodName(m.method))}</span></td><td>${signAmount(m)}</td>${actions?`<td>${m.category!=='reverso'&&!state.movements.some(r=>r.reversalOf===m.id)?button('Reversar','reverse-move','btn small danger',`data-id="${m.id}"`):`<span class="muted">${m.category==='reverso'?'Reverso':'Reversado'}</span>`}</td>`:''}</tr>`).join('')}</tbody></table></div><div class="mobile-records">${movs.map(m=>`<div class="mobile-record"><div class="mobile-record-top"><div><b>${esc(catName(m))}</b><small>${esc(dt(m.createdAt))}</small></div>${signAmount(m)}</div><div class="mobile-record-bottom"><div><small>${esc(m.party||m.note||'Sin tercero')}</small><span class="pill-method">${esc(methodName(m.method))}</span></div>${actions&&m.category!=='reverso'&&!state.movements.some(r=>r.reversalOf===m.id)?button('Reversar','reverse-move','btn small danger',`data-id="${m.id}"`):''}</div></div>`).join('')}</div></div>`}
function renderReports(){const from=ui.reportFrom,to=ui.reportTo;const movs=state.movements.filter(m=>{const date=localDate(new Date(m.createdAt));return date>=from&&date<=to});const docs=state.documents.filter(d=>{const day=localDate(new Date(d.createdAt));return day>=from&&day<=to});const incoming=sum(movs.filter(m=>m.direction==='in'),m=>m.amount),outgoing=sum(movs.filter(m=>m.direction==='out'),m=>m.amount);const grossSales=sum(docs.filter(d=>d.kind==='sale'),d=>d.total),grossPurch=sum(docs.filter(d=>d.kind==='purchase'),d=>d.total);const cashIn=sum(movs.filter(m=>m.method==='efectivo'&&m.direction==='in'),m=>m.amount),cashOut=sum(movs.filter(m=>m.method==='efectivo'&&m.direction==='out'),m=>m.amount);const methodstats=METHODS.map(m=>({name:m[1],total:sum(movs.filter(x=>x.method===m[0]),x=>x.amount)})).filter(x=>x.total>0).sort((a,b)=>b.total-a.total);const max=methodstats.length?methodstats[0].total:1;return `${pageTitle('Reportes y exportaciones','Consulta periodos y descarga respaldos de tus operaciones.',button(`${icon('download')} Exportar movimientos`,'export-moves','btn'))}<div class="panel" style="margin-bottom:19px"><div class="panel-body"><div class="form-grid"><div class="field"><label>Desde</label><input id="report-from" type="date" value="${esc(from)}"></div><div class="field"><label>Hasta</label><input id="report-to" type="date" value="${esc(to)}"></div></div></div></div><div class="metrics">${metric('Ingresos registrados',fmt(incoming),'Entradas reales por todos los métodos','coin','green')}${metric('Egresos registrados',fmt(outgoing),'Salidas reales por todos los métodos','wallet','pink')}${metric('Ventas documentadas',fmt(grossSales),'Incluye facturas a crédito','receipt')}${metric('Compras documentadas',fmt(grossPurch),'Incluye compras a crédito','briefcase','amber')}</div><div class="grid-2 grid-even"><section class="panel"><div class="panel-head"><div><h2>Medios de pago usados</h2><p>Volumen bruto de entradas y salidas</p></div></div><div class="panel-body">${methodstats.length?methodstats.map(m=>`<div class="method-line"><span>${esc(m.name)}</span><b>${fmt(m.total)}</b></div><div class="bar-bg"><div class="bar-fill" style="width:${Math.max(2,100*m.total/max)}%"></div></div>`).join(''):empty('Sin datos en este periodo','Amplía el periodo seleccionado.','pie')}</div></section><section class="panel"><div class="panel-head"><div><h2>Resumen del efectivo</h2><p>Entradas y salidas del periodo, sin bases de apertura</p></div></div><div class="panel-body"><div class="line-item"><span>Entradas en efectivo</span><b class="positive">${fmt(cashIn)}</b></div><div class="line-item"><span>Salidas en efectivo</span><b class="negative">${fmt(cashOut)}</b></div><div class="line-item"><span>Neto de movimientos en efectivo</span><b>${fmt(cashIn-cashOut)}</b></div><div class="section-spacer"></div><div class="hint">${icon('info')} <div>El neto no incluye bases iniciales ni saldos transportados entre turnos. Para saber cuánto debe haber en la gaveta, usa Caja y turnos.</div></div></div></section></div><div class="section-spacer"></div><section class="panel"><div class="panel-head"><div><h2>Descarga tus datos</h2><p>CSV para Excel y JSON para recuperar todo el historial</p></div></div><div class="panel-body actions">${button(`${icon('download')} CSV de movimientos`,'export-moves','btn')}${button(`${icon('download')} CSV de documentos`,'export-docs','btn')}${button(`${icon('download')} CSV de turnos`,'export-shifts','btn')}${button(`${icon('download')} Copia JSON completa`,'export-json','btn primary')}</div></section>`}
function renderMenu(){return `${pageTitle('Más módulos','Accede a todos los controles y reportes de Arqueo Express.')}<div class="panel"><div class="panel-body"><div class="action-grid">${NAV.filter(n=>!['inicio','caja','registrar'].includes(n[0])).map(n=>`<button type="button" class="action-tile" data-page="${n[0]}">${icon(n[1])}<div><b>${n[2]}</b><span>Abrir módulo</span></div></button>`).join('')}</div></div></div>`}
function renderSettings(){return `${pageTitle('Configuración','Identidad de tu negocio y administración de datos.') }<div class="grid-2 grid-even"><section class="panel"><div class="panel-head"><div><h2>Negocio</h2><p>Nombre visible en la aplicación y los reportes</p></div></div><div class="panel-body"><form id="settings-form"><div class="form-grid">${input('Nombre del negocio','name','text',state.settings.name,'maxlength="100" required')}<div class="field"><label>Moneda</label><input value="COP · Peso colombiano" disabled></div></div><div class="form-footer"><button class="btn primary" type="submit">Guardar cambios</button></div></form></div></section><section class="panel"><div class="panel-head"><div><h2>Seguridad de datos</h2><p>Esta versión trabaja únicamente en este navegador</p></div></div><div class="panel-body"><div class="hint warning">${icon('info')} <div>No hay cuentas ni sincronización. <b>Si borras los datos del navegador o cambias de equipo, puedes perder el historial.</b> Exporta una copia JSON periódicamente; no uses el almacenamiento local como único respaldo contable.</div></div><div class="section-spacer"></div><div class="actions">${button(`${icon('download')} Descargar respaldo`,'export-json','btn primary')}${button(`${icon('upload')} Restaurar respaldo`,'import-json','btn')}</div><input type="file" id="import-file" accept=".json,application/json"></div></section><section class="panel"><div class="panel-head"><div><h2>Pruebas y mantenimiento</h2><p>Opciones para explorar la microapp</p></div></div><div class="panel-body"><p class="muted" style="line-height:1.7">Prueba los flujos sin información real usando registros ficticios, o reinicia la aplicación. Estas acciones reemplazan los datos existentes.</p><div class="section-spacer"></div><div class="actions">${button('Cargar ejemplo ficticio','demo','btn')}${button('Borrar todos los datos','reset','btn danger')}</div></div></section><section class="panel"><div class="panel-head"><div><h2>Alcance de la versión 1.0</h2><p>Lo que Arqueo Express sí y no realiza</p></div></div><div class="panel-body"><div class="line-item"><span>Turnos, efectivo y arqueos</span><b class="positive">Incluido</b></div><div class="line-item"><span>Documentos de crédito y abonos</span><b class="positive">Incluido</b></div><div class="line-item"><span>Transferencias y pagos mixtos</span><b class="positive">Incluido</b></div><div class="line-item"><span>Nómina básica y anticipos</span><b class="positive">Incluido</b></div><div class="line-item"><span>Factura electrónica DIAN</span><b class="muted">No incluido</b></div><div class="line-item"><span>Sincronización multiusuario</span><b class="muted">No incluido</b></div></div></section></div>`}
function renderModal(){if(!ui.modal)return '';let title='',body='',footer='';const m=ui.modal;
 if(m.kind==='close'){
 const s=activeShift();if(!s)return '';const exp=shiftExpected(s);
 title='Arqueo y cierre del turno';
 body=`<div class="hint">${icon('info')} <div>Cuenta el dinero <b>antes de retirarlo de la gaveta</b>. El total se calcula de forma automática.</div></div><div class="section-spacer"></div><form id="close-form"><div class="kv"><span>Base de apertura</span><b>${fmt(s.base)}</b></div><div class="kv"><span>Efectivo esperado antes del retiro</span><b>${fmt(exp)}</b></div><div class="divider"></div><div class="denom-title-row"><div><h3>Conteo físico del cierre</h3><p>Introduce el número de piezas por denominación.</p></div><button type="button" class="btn small" data-action="clear-denoms" data-mode="closing">Borrar</button></div>${denominationCounter('closing',ui.closingDenoms)}<div class="counted-summary"><span>Efectivo contado</span><strong id="denom-total">${fmt(denominationTotal(ui.closingDenoms))}</strong></div><input type="hidden" name="counted" value="${denominationTotal(ui.closingDenoms)}"><div class="section-spacer"></div><div class="form-grid">${input('Base de efectivo que dejas para el siguiente turno','nextBase','number',Math.max(0,Math.min(s.base,exp)),'min="0" step="1" required inputmode="numeric"')}</div><div class="section-spacer"></div><div id="close-preview" class="hint">${icon('info')} <div>Ingresa las cantidades para comparar contra lo esperado.</div></div><div class="section-spacer"></div>${textarea('Observaciones de cierre','note','Faltantes, sobrantes y novedades')}<div class="form-footer"><button type="button" class="btn" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">${icon('check')} Confirmar cierre</button></div></form>`;
 }else if(m.kind==='doc'||m.kind==='pay'){
 const d=state.documents.find(x=>x.id===m.id);if(!d)return '';const paid=paidOf(d),due=balanceOf(d);title=m.kind==='pay'?(d.kind==='sale'?'Abono de cliente':'Pago a proveedor'):'Detalle del documento';const relevant=state.movements.filter(x=>x.documentId===d.id);
 if(m.kind==='pay'){
 body=`<div class="line-item"><div><b>${esc(d.party)}</b><small>${esc(d.number)} · ${d.kind==='sale'?'Cliente':'Proveedor'}</small></div><div style="text-align:right"><small>Saldo máximo</small><b class="money value-large">${fmt(due)}</b></div></div><div class="section-spacer"></div><form id="payment-form" data-id="${d.id}"><div class="form-grid">${input('Referencia (opcional)','reference','text','','placeholder="Comprobante o concepto" maxlength="100"')}</div>${paymentBlock()}<div class="form-footer"><button type="button" class="btn" data-action="close-modal">Cancelar</button><button type="submit" class="btn primary">${icon('check')} Guardar abono</button></div></form>`;
 }else{
 body=`<div class="kv"><span>Tipo</span><b>${d.kind==='sale'?'Factura de venta':'Factura de compra'}</b></div><div class="kv"><span>Número</span><b>${esc(d.number)}</b></div><div class="kv"><span>Tercero</span><b>${esc(d.party)}</b></div><div class="kv"><span>Fecha</span><b>${esc(dateOnly(d.createdAt))}</b></div><div class="kv"><span>Concepto</span><b>${esc(d.note||'—')}</b></div><div class="divider"></div><div class="kv"><span>Valor total</span><b>${fmt(d.total)}</b></div><div class="kv"><span>Pagado</span><b>${fmt(paid)}</b></div><div class="kv"><span>Saldo pendiente</span><b class="value-large">${fmt(due)}</b></div><div class="kv"><span>Estado</span>${statusBadge(d)}</div><div class="divider"></div><h3>Historial de pagos</h3>${relevant.length?relevant.map(x=>`<div class="line-item"><div><b>${esc(catName(x))}</b><small>${esc(dt(x.createdAt))} · ${esc(methodName(x.method))}</small></div>${signAmount(x)}</div>`).join(''):`<p class="muted" style="margin-top:15px">Sin pagos. El valor completo está a crédito.</p>`}<div class="section-spacer"></div><div class="actions">${due>0?button(`${icon('plus')} ${d.kind==='sale'?'Registrar abono':'Pagar al proveedor'}`,'pay-doc','btn primary',`data-id="${d.id}"`):''}${button('Cerrar','close-modal','btn')}</div>`;
 }
 }else if(m.kind==='shift'){
 const s=state.shifts.find(x=>x.id===m.id);if(!s)return '';title='Comprobante de cierre';const cashM=shiftMovements(s.id).filter(x=>x.method==='efectivo');const entries=sum(cashM.filter(x=>x.direction==='in'),x=>x.amount),exits=sum(cashM.filter(x=>x.direction==='out'),x=>x.amount);body=`<div class="print-preview"><h2>${esc(state.settings.name)}</h2><p>Arqueo Express · Comprobante interno de cierre de caja</p><div class="divider"></div><div class="kv"><span>Responsable</span><b>${esc(s.operator)}</b></div><div class="kv"><span>Apertura</span><b>${esc(dt(s.openedAt))}</b></div><div class="kv"><span>Cierre</span><b>${esc(dt(s.closedAt))}</b></div><div class="divider"></div><div class="kv"><span>Base inicial</span><b>${fmt(s.base)}</b></div>${s.baseDenominations?`<div class="kv"><span>Piezas contadas en apertura</span><b>${sum(Object.values(s.baseDenominations),num)}</b></div>`:''}<div class="kv"><span>Entradas en efectivo</span><b>${fmt(entries)}</b></div><div class="kv"><span>Salidas en efectivo</span><b>${fmt(exits)}</b></div><div class="kv"><span>Efectivo esperado</span><b>${fmt(s.expected)}</b></div><div class="kv"><span>Efectivo contado (antes del retiro)</span><b>${fmt(s.counted)}</b></div><div class="kv"><span>Diferencia (sobrante / faltante)</span><b class="${s.difference===0?'':s.difference>0?'positive':'negative'}">${fmt(s.difference)}</b></div><div class="divider"></div><div class="kv"><span>Retiro físico de cierre</span><b>${fmt(s.withdrawal)}</b></div><div class="kv"><span>Base dejada para siguiente turno</span><b>${fmt(s.nextBase)}</b></div><div class="kv"><span>Novedades</span><b>${esc(s.note||'—')}</b></div><div class="divider"></div><p style="font-size:11px;color:#7d899d">Este documento es un soporte interno. No sustituye soporte fiscal o contable.</p></div>`;footer=`${button(`${icon('printer')} Imprimir / guardar PDF`,'print','btn primary')}${button('Cerrar','close-modal','btn')}`;
 }else if(m.kind==='reverse'){
 const entry=state.movements.find(x=>x.id===m.id);if(!entry)return '';title='Reversar movimiento';body=`<div class="hint warning">${icon('info')} <div>No se borra el movimiento original. Se creará una operación opuesta dentro del turno actual, conservando trazabilidad.</div></div><div class="section-spacer"></div><div class="line-item"><div><b>${esc(catName(entry))}</b><small>${esc(methodName(entry.method))} · ${esc(dt(entry.createdAt))}</small></div>${signAmount(entry)}</div><div class="section-spacer"></div><form id="reverse-form" data-id="${entry.id}"><div class="field"><label>Motivo del reverso</label><textarea name="reason" required maxlength="300" placeholder="Ejemplo: registro duplicado"></textarea></div><div class="form-footer"><button type="button" class="btn" data-action="close-modal">Cancelar</button><button type="submit" class="btn danger">Confirmar reverso</button></div></form>`;
 }
 return `<div class="modal-cover" data-action="outside-close"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button type="button" class="modal-x" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div><div class="modal-content">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</div></div>`}
function validateDocForm(form){const party=form.party.value.trim(),total=num(form.total.value);if(!party)throw Error('Escribe el nombre del cliente o proveedor.');if(!Number.isFinite(total)||total<=0)throw Error('El valor de la factura debe ser mayor que cero.');const payments=readPayments(form,total);if(form.date.value>localDate())throw Error('No registres una factura con fecha futura.');return {party,total,payments}}
function applyDocForm(form){if(!requireShift())return;try{const {party,total,payments}=validateDocForm(form);const kind=ui.registerTab==='venta'?'sale':'purchase';const manual=form.number.value.trim();let number=manual||`${kind==='sale'?'VTA':'CMP'}-${String(state.documents.filter(d=>d.kind===kind).length+1).padStart(5,'0')}`;if(state.documents.some(d=>d.kind===kind&&d.number.toLowerCase()===number.toLowerCase()))throw Error('Ya existe un documento con ese número.');const id=uid();commit(()=>{state.documents.push({id,kind,number,party,total,createdAt:`${form.date.value}T12:00:00`,recordedAt:new Date().toISOString(),note:form.note.value.trim()});for(const p of payments)addMovement({category:kind==='sale'?'venta':'compra',direction:kind==='sale'?'in':'out',amount:p.amount,method:p.method,party,documentId:id,reference:number,note:form.note.value.trim()})},`${kind==='sale'?'Venta':'Compra'} guardada. ${total>sum(payments,p=>p.amount)?'Saldo a crédito registrado.':'Pago completo.'}`);ui.page='documentos';render()}catch(e){toast(e.message,'error')}}
function applyFlowForm(form){if(!requireShift())return;const def=FLOW_TYPES.find(x=>x[0]===form.category.value);if(!def)return;const amount=num(form.amount.value);if(amount<=0){toast('Introduce un valor mayor a cero.','error');return}const method=['retiro','ingreso_caja'].includes(def[0])?'efectivo':form.elements.namedItem('method').value;if(method==='efectivo'&&def[2]==='out'&&shiftExpected(activeShift())<amount){if(!confirm('El valor supera el efectivo esperado de la caja. ¿Registrar esta salida de todos modos?'))return}commit(()=>addMovement({category:def[0],direction:def[2],amount,method,party:form.party.value.trim(),reference:form.reference.value.trim(),note:form.note.value.trim()}),'Movimiento registrado.');form.reset()}
function applyAdvanceForm(form){if(!requireShift())return;const employee=form.employee.value.trim(),amount=num(form.amount.value);if(!employee||amount<=0){toast('Escribe el empleado y un monto positivo.','error');return}commit(()=>addMovement({category:'anticipo',direction:'out',method:form.elements.namedItem('method').value,amount,party:employee,reference:form.reference.value.trim(),note:form.note.value.trim()}),'Adelanto registrado; disponible para descontar de nómina.');form.reset()}
function calculatePayroll(form){const employee=form.employee.value.trim(),gross=num(form.gross.value),available=remainingAdvance(employee),deduct=form.deduct.checked?Math.min(gross,available):0;return {employee,gross,deduct,net:Math.max(0,gross-deduct)}}
function updatePayroll(){const form=document.getElementById('payroll-form');if(!form)return;const p=calculatePayroll(form);const set=(id,s)=>{const el=document.getElementById(id);if(el)el.textContent=s};set('advance-info',`Anticipos sin aplicar: ${fmt(remainingAdvance(p.employee))}`);set('pay-gross',fmt(p.gross));set('pay-deduct',fmt(p.deduct));set('pay-net',fmt(p.net))}
function applyPayrollForm(form){if(!requireShift())return;const p=calculatePayroll(form);if(!p.employee||p.gross<=0){toast('Ingresa empleado y valor devengado válido.','error');return}const id=uid();commit(()=>{state.payrolls.push({id,createdAt:new Date().toISOString(),employee:p.employee,gross:p.gross,appliedAdvance:p.deduct,net:p.net,method:form.elements.namedItem('method').value,reference:form.reference.value.trim(),note:form.note.value.trim(),voided:false});if(p.net>0)addMovement({category:'nomina',direction:'out',method:form.elements.namedItem('method').value,amount:p.net,party:p.employee,reference:form.reference.value.trim(),note:form.note.value.trim(),payrollId:id})},`Nómina registrada. Neto pagado: ${fmt(p.net)}.`);ui.page='nomina';render()}
function applyAbono(form){if(!requireShift())return;const d=state.documents.find(x=>x.id===form.dataset.id);if(!d)return;const due=balanceOf(d);try{const payments=readPayments(form,due),total=sum(payments,p=>p.amount);if(!total)throw Error('Ingresa un monto de abono positivo.');const category=d.kind==='sale'?'abono_cliente':'abono_proveedor',direction=d.kind==='sale'?'in':'out';commit(()=>{payments.forEach(p=>addMovement({category,direction,amount:p.amount,method:p.method,party:d.party,reference:form.reference.value.trim()||d.number,documentId:d.id,note:`Abono a ${d.number}`}))},`Abono de ${fmt(total)} registrado.`);ui.modal=null;render()}catch(e){toast(e.message,'error')}}
function openShift(form){
 if(activeShift()){toast('Ya existe un turno abierto.','error');return}
 const operator=form.operator.value.trim();let counts;
 try{counts=readDenominationCounts(form)}catch(e){toast(e.message,'error');return}
 const base=denominationTotal(counts);
 if(!operator){toast('Escribe el nombre del responsable.','error');return}
 if(!confirm(`¿Abrir caja a nombre de ${operator} con una base física de ${fmt(base)}?`))return;
 if(commit(()=>state.shifts.push({id:uid(),openedAt:new Date().toISOString(),operator,base,baseDenominations:counts,openNote:form.note.value.trim(),status:'open'}),'Caja abierta. El conteo quedó guardado.'))ui.openingDenoms={};
}
function closeShift(form){
 const shift=activeShift();if(!shift)return;
 let counts;try{counts=readDenominationCounts(form)}catch(e){toast(e.message,'error');return}
 const counted=denominationTotal(counts),nextBase=Number(form.nextBase.value);
 if(!Number.isSafeInteger(nextBase)||nextBase<0){toast('Registra una base válida.','error');return}
 if(nextBase>counted){toast('La base a dejar no puede superar el efectivo contado.','error');return}
 const expected=shiftExpected(shift),difference=counted-expected,withdrawal=counted-nextBase;
 if(!confirm(`Resumen del cierre:\nContado: ${fmt(counted)}\nEsperado: ${fmt(expected)}\nDiferencia: ${fmt(difference)}\nRetiro: ${fmt(withdrawal)}\nBase siguiente: ${fmt(nextBase)}\n\n¿Confirmar cierre de caja?`))return;
 const id=shift.id;
 if(commit(()=>Object.assign(shift,{status:'closed',closedAt:new Date().toISOString(),counted,countedDenominations:counts,nextBase,difference,expected,withdrawal,note:form.note.value.trim()}),`Turno cerrado. Diferencia: ${fmt(difference)}.`)){
 ui.closingCount='';ui.closingDenoms={};ui.modal={kind:'shift',id};render();
 }
}
function createReverse(m,reason){if(!requireShift())return;const orig=state.movements.find(x=>x.id===m);if(!orig||orig.category==='reverso'||state.movements.some(x=>x.reversalOf===orig.id)){toast('Este registro no puede reversarse.','error');return}if(orig.category==='nomina'){toast('Para reversar nómina usa la opción Anular en el módulo Nómina.','error');return}if(orig.category==='anticipo'&&remainingAdvance(orig.party)<orig.amount){toast('Este anticipo ya se aplicó en nómina. Debes corregir la liquidación antes de reversarlo.','error');return}commit(()=>{addMovement({category:'reverso',direction:orig.direction==='in'?'out':'in',amount:orig.amount,method:orig.method,party:orig.party||'',reference:orig.reference||'',documentId:orig.documentId||null,note:reason,reversalOf:orig.id});if(orig.payrollId){const pay=state.payrolls.find(p=>p.id===orig.payrollId);if(pay)pay.voided=true}},'Reverso registrado sin borrar el movimiento original.');ui.modal=null;render()}
function calculateDens(){return updateDenominationCounter('closing')}
function updateClosePreview(){
 const form=document.getElementById('close-form');if(!form)return;
 const preview=document.getElementById('close-preview'),shift=activeShift();if(!shift||!preview)return;
 const counted=denominationTotal(ui.closingDenoms),base=Number(form.nextBase.value)||0,diff=counted-shiftExpected(shift);
 preview.className=`hint ${diff!==0?'warning':''}`;
 preview.innerHTML=`${icon('info')} <div><b>${diff===0?'Caja cuadrada':diff>0?'Sobrante':'Faltante'}: ${fmt(Math.abs(diff))}</b><div>Retiro al cierre: <b>${fmt(Math.max(0,counted-base))}</b> · Base siguiente: <b>${fmt(base)}</b>.</div>${base>counted?'<strong class="negative">La base dejada supera el dinero contado.</strong>':''}</div>`;
}
function getCsvRows(type){if(type==='moves')return [['Fecha','Turno','Tipo','Dirección','Tercero','Método','Valor_COP','Documento','Referencia','Concepto','Reversa_de'],...state.movements.map(m=>[m.createdAt,m.shiftId,m.category,m.direction,m.party||'',methodName(m.method),m.amount,m.documentId||'',m.reference||'',m.note||'',m.reversalOf||''])];if(type==='docs')return [['Fecha','Tipo','Numero','Tercero','Total_COP','Pagado_COP','Saldo_COP','Estado','Concepto'],...state.documents.map(d=>[d.createdAt,d.kind,d.number,d.party,d.total,paidOf(d),balanceOf(d),statusOf(d),d.note||''])];return [['Apertura','Cierre','Responsable','Base_inicial_COP','Esperado_COP','Contado_COP','Diferencia_COP','Retiro_COP','Base_siguiente_COP','Estado','Novedades'],...state.shifts.map(s=>[s.openedAt,s.closedAt||'',s.operator,s.base,s.expected??'',s.counted??'',s.difference??'',s.withdrawal??'',s.nextBase??'',s.status,s.note||''])]}
function download(filename,text,type){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function exportCSV(which){const csv=getCsvRows(which).map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\r\n');download(`arqueo-${which}-${localDate()}.csv`,'\ufeff'+csv,'text/csv;charset=utf-8');toast('Archivo CSV generado.')} 
function exportJSON(){download(`arqueo-backup-${localDate()}.json`,JSON.stringify(state,null,2),'application/json;charset=utf-8');toast('Copia de seguridad descargada.')} 
function importJSON(file){const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!validData(data))throw Error('Archivo incompatible: estructura incorrecta.');if(!confirm('Esto reemplazará TODOS los registros actuales por los datos del archivo. ¿Continuar?'))return;state=data;save();ui.modal=null;ui.page='inicio';render();toast('Copia restaurada correctamente.')}catch(e){toast(e.message,'error')}};reader.onerror=()=>toast('No se pudo leer el archivo.','error');reader.readAsText(file)}
function makeDemo(){const now=new Date(),ago=(h)=>new Date(now.getTime()-h*36e5).toISOString(),shiftId=uid(),d1=uid(),d2=uid(),d3=uid();const movements=[
 {id:uid(),createdAt:ago(5),shiftId,category:'venta',direction:'in',amount:135000,method:'efectivo',party:'Cliente mostrador',documentId:d1,reference:'VTA-00001'},
 {id:uid(),createdAt:ago(4),shiftId,category:'venta',direction:'in',amount:75000,method:'nequi',party:'Cliente mostrador',documentId:d1,reference:'VTA-00001'},
 {id:uid(),createdAt:ago(3),shiftId,category:'venta',direction:'in',amount:50000,method:'efectivo',party:'Distribuidora Centro',documentId:d2,reference:'VTA-00002'},
 {id:uid(),createdAt:ago(2.5),shiftId,category:'compra',direction:'out',amount:40000,method:'transferencia',party:'Proveedor del Norte',documentId:d3,reference:'CMP-00001'},
 {id:uid(),createdAt:ago(2),shiftId,category:'gasto',direction:'out',amount:18500,method:'efectivo',party:'Transporte local',note:'Mensajería'},
 {id:uid(),createdAt:ago(1),shiftId,category:'anticipo',direction:'out',amount:30000,method:'nequi',party:'María López',note:'Adelanto quincena'}];
 return {version:1,settings:{name:'Tienda de ejemplo'},shifts:[{id:shiftId,openedAt:ago(8),operator:'Cajero de muestra',base:150000,status:'open'}],documents:[{id:d1,kind:'sale',createdAt:ago(5),number:'VTA-00001',party:'Cliente mostrador',total:210000,note:'Venta mixta'},{id:d2,kind:'sale',createdAt:ago(3),number:'VTA-00002',party:'Distribuidora Centro',total:270000,note:'Crédito con abono'},{id:d3,kind:'purchase',createdAt:ago(2.5),number:'CMP-00001',party:'Proveedor del Norte',total:160000,note:'Compra parcialmente pagada'}],movements,payrolls:[]}}
function updatePaymentTotals(){const form=document.querySelector('#document-form, #payment-form');if(!form)return;const paid=sum([...form.querySelectorAll('[name=pay_amount]')],i=>num(i.value));const max=form.id==='document-form'?num(form.querySelector('[name=total]').value):balanceOf(state.documents.find(d=>d.id===form.dataset.id));const a=form.querySelector('.calc-paid'),b=form.querySelector('.calc-credit');if(a)a.textContent=fmt(paid);if(b)b.textContent=fmt(Math.max(0,max-paid));const el=form.querySelector('.payment-total');if(el)el.style.color=paid>max?'#b23b47':''}
function resetAndRender(){ui.modal=null;render();window.scrollTo({top:0,behavior:'instant'})}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action],[data-page],[data-tab],[data-doc-filter],[data-credit-tab]');if(!btn)return;
 if(btn.hasAttribute('data-page')){ui.page=btn.dataset.page;resetAndRender();return}
 if(btn.hasAttribute('data-tab')&&!btn.hasAttribute('data-action')){ui.registerTab=btn.dataset.tab;render();return}
 if(btn.hasAttribute('data-doc-filter')){ui.docTab=btn.dataset.docFilter;render();return}
 if(btn.hasAttribute('data-credit-tab')){ui.creditTab=btn.dataset.creditTab;render();return}
 const action=btn.dataset.action;
 if(action==='outside-close'){if(e.target===btn){ui.modal=null;render()}return}
 if(action==='close-modal'){ui.modal=null;render();return}
 if(action==='goto-register'){ui.page='registrar';resetAndRender();return}
 if(action==='goto-movimientos'){ui.page='movimientos';resetAndRender();return}
 if(action==='goto-caja'){ui.page='caja';resetAndRender();return}
 if(action==='goto-payroll'){ui.page='registrar';ui.registerTab='nomina';resetAndRender();return}
 if(action==='quick'){ui.page=btn.dataset.pageTarget;if(btn.dataset.tab)ui.registerTab=btn.dataset.tab;resetAndRender();return}
 if(action==='show-close'){ui.modal={kind:'close'};ui.closingCount='';ui.closingDenoms={};render();updateClosePreview();return}
 if(action==='view-shift'){ui.modal={kind:'shift',id:btn.dataset.id};render();return}
 if(action==='view-doc'){ui.modal={kind:'doc',id:btn.dataset.id};render();return}
 if(action==='pay-doc'){if(!requireShift())return;ui.modal={kind:'pay',id:btn.dataset.id};render();updatePaymentTotals();return}
 if(action==='add-payment'){const payments=btn.closest('form').querySelector('.payments');if(payments&&payments.querySelectorAll('.payment-row').length<6){payments.insertAdjacentHTML('beforeend',paymentRow());updatePaymentTotals()}return}
 if(action==='remove-payment'){const row=btn.closest('.payment-row'),container=btn.closest('.payments');if(container&&container.children.length>1)row.remove();else row.querySelector('[name=pay_amount]').value='';updatePaymentTotals();return}
 if(action==='change-denom'){const mode=btn.dataset.mode,key=btn.dataset.key,delta=Number(btn.dataset.delta);const root=document.querySelector(`.cash-denom-counter[data-mode="${mode}"]`),field=root?.querySelector(`[name="denom_${key}"]`);if(!field||!Number.isFinite(delta))return;field.value=Math.max(0,Math.min(100000,num(field.value)+delta))||'';updateDenominationCounter(mode);return}
 if(action==='clear-denoms'){const mode=btn.dataset.mode;const root=document.querySelector(`.cash-denom-counter[data-mode="${mode}"]`);if(!root)return;if(!confirm('¿Poner todas las cantidades en cero?'))return;root.querySelectorAll('.denom-qty').forEach(el=>el.value='');updateDenominationCounter(mode);return}
 if(action==='reverse-move'){if(!requireShift())return;ui.modal={kind:'reverse',id:btn.dataset.id};render();return}
 if(action==='reverse-payroll'){if(!requireShift())return;const p=state.payrolls.find(x=>x.id===btn.dataset.id);if(!p||p.voided)return;if(!confirm(`Anular la liquidación de ${p.employee} por ${fmt(p.gross)} y registrar un reverso del pago neto?`))return;commit(()=>{p.voided=true;const related=state.movements.find(m=>m.payrollId===p.id&&m.category==='nomina');if(related)addMovement({category:'reverso',direction:'in',amount:related.amount,method:related.method,party:p.employee,reference:related.reference||'',note:'Anulación de nómina '+p.id,reversalOf:related.id})},'Nómina anulada; anticipo aplicado liberado.');return}
 if(action==='print'){window.print();return}
 if(action==='export-moves'){exportCSV('moves');return}
 if(action==='export-docs'){exportCSV('docs');return}
 if(action==='export-shifts'){exportCSV('shifts');return}
 if(action==='export-json'){exportJSON();return}
 if(action==='import-json'){document.getElementById('import-file')?.click();return}
 if(action==='demo'){if(!confirm('Cargar un ejemplo eliminará todos los datos actuales de este navegador. ¿Continuar?'))return;state=makeDemo();save();ui.page='inicio';resetAndRender();toast('Ejemplo cargado con datos ficticios.');return}
 if(action==='reset'){if(!confirm('ATENCIÓN: se borrarán TODOS los registros guardados. Descarga un respaldo antes de continuar. ¿Borrar todo?'))return;if(!confirm('Confirmar borrado definitivo de este navegador.'))return;state=defaultState();save();ui.page='inicio';resetAndRender();toast('Datos locales reiniciados.');return}
});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;switch(f.id){case 'open-shift-form':openShift(f);break;case 'close-form':closeShift(f);break;case 'document-form':applyDocForm(f);break;case 'flow-form':applyFlowForm(f);break;case 'advance-form':applyAdvanceForm(f);break;case 'payroll-form':applyPayrollForm(f);break;case 'payment-form':applyAbono(f);break;case 'reverse-form':if(!f.reason.value.trim()){toast('El reverso necesita un motivo.','error');return}createReverse(f.dataset.id,f.reason.value.trim());break;case 'settings-form':commit(()=>state.settings.name=f.elements.namedItem('name').value.trim()||'Mi negocio','Nombre actualizado.');break}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='doc-search'){ui.docSearch=t.value;const start=t.selectionStart;const docs=ui.docSearch;const filtered=[...state.documents].reverse().filter(d=>(ui.docTab==='todos'||(ui.docTab==='venta'?d.kind==='sale':d.kind==='purchase'))&&(`${d.party} ${d.number} ${d.note||''}`.toLowerCase().includes(docs.toLowerCase())));const panel=document.querySelector('#doc-search')?.closest('.panel');if(panel){const table=panel.querySelector('.records-list, .empty');if(table)table.outerHTML=renderDocsTable(filtered,true)}return}
 if(t.id==='mov-search'){ui.movSearch=t.value;let movs=[...state.movements].reverse().filter(m=>ui.movFilter==='todos'||(ui.movFilter==='entrada'?m.direction==='in':ui.movFilter==='salida'?m.direction==='out':m.method===ui.movFilter));movs=movs.filter(m=>`${m.party||''} ${m.note||''} ${m.reference||''} ${catName(m)} ${methodName(m.method)}`.toLowerCase().includes(ui.movSearch.toLowerCase()));const panel=t.closest('.panel');const table=panel?.querySelector('.records-list, .empty');if(table)table.outerHTML=renderMovTable(movs,true);return}
 if(t.matches('[name=pay_amount]')||t.matches('#document-form [name=total]'))updatePaymentTotals();
 if(t.closest('#payroll-form'))updatePayroll();
 if(t.matches('.denom-qty')){updateDenominationCounter(t.dataset.counter);return}
 if(t.closest('#close-form')&&t.matches('[name=nextBase]'))updateClosePreview();
});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='mov-filter'){ui.movFilter=el.value;render();return}if(el.id==='report-from'){ui.reportFrom=el.value;render();return}if(el.id==='report-to'){ui.reportTo=el.value;render();return}if(el.id==='import-file'){if(el.files?.[0])importJSON(el.files[0]);return}if(el.closest('#payroll-form'))updatePayroll();if(el.closest('.payment-row'))updatePaymentTotals();if(el.id==='f_category'){const type=el.value;const method=el.closest('form')?.querySelector('[name=method]');if(method){method.disabled=['retiro','ingreso_caja'].includes(type);if(method.disabled)method.value='efectivo'}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal){ui.modal=null;render()}});
render();
